/// <summary>
/// CB202_SalesQuotaMinMax
/// Refactor search code to return a <c>METAgreementLineSearchResult</c> object
/// </summary>
final class METAgreementLineSearchResult
{
    SalesAgreementHeader    salesAgreementHeader;
    AgreementLine           agreementLine;
    AgreementClassification agreementClassification;

}

Method.Source:
/// <summary>
/// Get the SA header retrieved from the search
/// </summary>
/// <returns><c>SalesAgreementHeader</c> record; otherwise, null.</returns>
SalesAgreementHeader getSalesAgreementHeader()
{
    return salesAgreementHeader;
}

/// <summary>
/// Get the SA line retrieved from the search
/// </summary>
/// <returns><c>AgreementLine</c> record; otherwise, null.</returns>
AgreementLine getAgreementLine()
{
    return agreementLine;
}

/// <summary>
/// Get the SA classification retrieved from the search
/// </summary>
/// <returns><c>AgreementClassification</c> record; otherwise, null.</returns>
AgreementClassification getAgreementClassification()
{
    return agreementClassification;
}

/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesAgreementHeader"><c>SalesAgreementHeader</c> record</param>
/// <param name = "_agreementLine"><c>AgreementLine</c> record</param>
/// <param name = "_agreementClassification"><c>AgreementClassification</c> record</param>
/// <returns>Instance of class <c>METAgreementLineSearchResult</c></returns>
public static METAgreementLineSearchResult contruct(SalesAgreementHeader    _salesAgreementHeader, 
                                                    AgreementLine           _agreementLine,
                                                    AgreementClassification _agreementClassification)
{
    return new METAgreementLineSearchResult(_salesAgreementHeader, _agreementLine, _agreementClassification);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesAgreementHeader"><c>SalesAgreementHeader</c> record</param>
/// <param name = "_agreementLine"><c>AgreementLine</c> record</param>
/// <param name = "_agreementClassification"><c>AgreementClassification</c> record</param>
protected void new(SalesAgreementHeader     _salesAgreementHeader,
                   AgreementLine            _agreementLine,
                   AgreementClassification  _agreementClassification)
{
    salesAgreementHeader = _salesAgreementHeader;
    agreementLine = _agreementLine;
    agreementClassification = _agreementClassification;
}
